// --- TWELVE VILLARCEAU CIRCLES OF ONE TORUS ---
// Torus with radii A (guide) and B (tube). With c = sqrt(A^2-B^2)/A and
// s = B/A the circle
//     (A*c*cos(u), B + A*sin(u), A*s*cos(u))
// lies on the torus for every u: an oblique section through a bitangent plane.
// One tube per MESH_BEGIN section, turned by mesh*TAU/12 around z: all circles
// of the same family, which do not meet while the tubes stay thin. The odd
// tubes are half as thick (thickness: 0.5).
//MESH_BEGIN
u: 0, TAU, 200
v: 0, TAU, 32
//MESH_END
//MESH_BEGIN
u: 0, TAU, 200
v: 0, TAU, 32
thickness: 0.5
//MESH_END
