u: 0, TAU, 200
v: 0, TAU, 32
thickness: 0.5
//MESH_END
float c = sqrt(A*A - B*B) / A;
float s = B / A;
float a = mesh * 0.52359878;
vec3 q = vec3(A*c*cos(u), B + A*sin(u), A*s*cos(u));
return vec4(q.x*cos(a) - q.y*sin(a), q.x*sin(a) + q.y*cos(a), q.z, 0.0);
